import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Sparkles, AlertCircle } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'CONTROL MAESTRO';
      case UserRole.ADMIN: return 'GESTIÓN CENTRAL';
      case UserRole.HEAD: return 'JEFATURA DE ÁREA';
      default: return 'CUERPO TÉCNICO';
  }
};

const getUserAvatarStyle = (user: User) => {
    switch (user.role) {
        case UserRole.SUPERADMIN:
            return 'bg-slate-900 text-white border-transparent';
        case UserRole.ADMIN:
            return 'bg-white text-red-500 border-red-100 border-2';
        case UserRole.HEAD:
            return 'bg-white text-indigo-600 border-indigo-100 border-2';
        default:
            return 'bg-white text-slate-400 border-slate-100 border-2';
    }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-4 p-4 hover:bg-slate-50/80 transition-all text-left group border-b border-slate-50 last:border-0"
    >
      <div className={`w-11 h-11 rounded-xl flex items-center justify-center font-black text-xs transition-all shadow-sm group-hover:scale-105 ${getUserAvatarStyle(user)}`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0">
          <div className="text-[14px] font-black text-slate-800 group-hover:text-indigo-600 truncate uppercase tracking-tight leading-none mb-1.5">{user.name}</div>
          <div className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.1em] truncate">
            {user.area ? user.area.toUpperCase() : getRoleLabel(user.role)}
          </div>
      </div>
      {isSelected && <div className="bg-indigo-600 p-1.5 rounded-full text-white shadow-lg"><Check size={12} strokeWidth={4}/></div>}
    </button>
);

