import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { User, UserRole, UserStatus } from '../types';
import { User as UserIcon, Edit2, Activity, UserPlus, Calendar, Shield, Briefcase, Mail, Power, Search } from 'lucide-react';
import { NewUserModal } from './NewUserModal';

const getUserAvatarStyle = (user: User) => {
    switch (user.role) {
        case UserRole.SUPERADMIN:
            return 'bg-slate-900 text-white border-transparent shadow-md shadow-slate-200';
        case UserRole.ADMIN:
            return 'bg-white text-red-500 border-red-100 border-2 shadow-sm shadow-red-50';
        case UserRole.HEAD:
            return 'bg-white text-indigo-600 border-indigo-100 border-2 shadow-sm shadow-indigo-50';
        default:
            return 'bg-white text-slate-400 border-slate-100 border-2 shadow-sm';
    }
};

export const UsersView: React.FC = () => {
  const { users } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const stats = useMemo(() => {
    const total = users.length;
    const active = users.filter(u => u.status === 'ACTIVE' || !u.status).length;
    const inactive = total - active;
    const roles = {
        [UserRole.SUPERADMIN]: users.filter(u => u.role === UserRole.SUPERADMIN).length,
        [UserRole.ADMIN]: users.filter(u => u.role === UserRole.ADMIN).length,
        [UserRole.HEAD]: users.filter(u => u.role === UserRole.HEAD).length,
        [UserRole.ANALYST]: users.filter(u => u.role === UserRole.ANALYST).length,
    };
    return { total, active, inactive, roles };
  }, [users]);

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.email?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const handleEditClick = (user: User) => {
    setSelectedUser(user);
    setIsModalOpen(true);
  };

  const handleNewUserClick = () => {
    setSelectedUser(null);
    setIsModalOpen(true);
  };

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 bg-[#F8FAFC]">

        {/* Header con Buscador y Acción */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
            <div className="flex flex-col gap-2">
                <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Directorio Institucional</h2>
                <div className="flex items-center gap-3">
                    <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[10px] font-black border border-indigo-100 uppercase tracking-widest">
                        {stats.total} Colaboradores Registrados
                    </span>
                    <div className="w-1.5 h-1.5 rounded-full bg-slate-200"></div>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sincronizado con Active Directory</span>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <div className="relative group">
                    <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors"/>
                    <input 
                        type="text"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder="Buscar por nombre o correo..."
                        className="pl-14 pr-8 py-4 bg-white border-2 border-slate-100 rounded-2xl w-full md:w-[350px] text-sm font-bold shadow-inner focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300"
                    />
                </div>
                <button 
                    onClick={handleNewUserClick}
                    className="bg-slate-900 hover:bg-slate-800 text-white px-8 py-4 rounded-2xl shadow-2xl shadow-slate-200 flex items-center justify-center gap-3 text-xs font-black uppercase tracking-[0.2em] transition-all active:scale-95 whitespace-nowrap"
                >
                    <UserPlus size={18} strokeWidth={3}/> Alta de Usuario
                </button>
            </div>
        </div>

        {/* Métrica de Roles */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {[
                { label: 'Control Maestro', val: stats.roles.SUPERADMIN, color: 'bg-slate-900', icon: <Shield size={16}/> },
                { label: 'Gestión Central', val: stats.roles.ADMIN, color: 'bg-red-500', icon: <Shield size={16}/> },
                { label: 'Jefaturas', val: stats.roles.HEAD, color: 'bg-indigo-600', icon: <Briefcase size={16}/> },
                { label: 'Analistas', val: stats.roles.ANALYST, color: 'bg-slate-400', icon: <UserIcon size={16}/> },
            ].map((r, i) => (
                <div key={i} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between">
                    <div>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1.5">{r.label}</p>
                        <p className="text-2xl font-black text-slate-800">{r.val}</p>
                    </div>
                    <div className={`${r.color} p-3 rounded-2xl text-white shadow-lg`}>{r.icon}</div>
                </div>
            ))}
        </div>

        {/* Lista de Usuarios Estilizada */}
        <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl shadow-slate-200/50 overflow-hidden">
             <div className="grid grid-cols-[1fr_1.5fr_1.5fr_1fr_1fr_100px] gap-4 px-10 py-6 bg-slate-50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                <div>Colaborador</div>
                <div>Rol Operativo</div>
                <div>Unidad Orgánica</div>
                <div>Estado de Cuenta</div>
                <div>Fecha de Alta</div>
                <div className="text-right">Gestión</div>
             </div>

             <div className="divide-y divide-slate-50">
                {filteredUsers.map(user => (
                    <div 
                        key={user.id} 
                        className="grid grid-cols-[1fr_1.5fr_1.5fr_1fr_1fr_100px] gap-4 px-10 py-6 items-center hover:bg-slate-50/50 transition-all group"
