                                {user.name.substring(0,2).toUpperCase()}
                            </div>
                            <div className="min-w-0">
                                <div className="font-black text-slate-800 text-[14px] truncate uppercase tracking-tight group-hover:text-indigo-600 transition-colors">{user.name}</div>
                                <div className="text-[10px] text-slate-400 font-bold truncate lowercase mt-1">{user.email || 'Sin e-mail institucional'}</div>
                            </div>
                        </div>

                        {/* Role */}
                        <div>
                            <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black border uppercase tracking-widest flex items-center gap-2.5 w-fit ${
