                                user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 border-red-100' :
                                user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                'bg-slate-50 text-slate-500 border-slate-200'
                            }`}>
                                {user.role === UserRole.SUPERADMIN ? <Shield size={10} /> : user.role === UserRole.HEAD ? <Briefcase size={10}/> : <UserIcon size={10}/>}
                                {user.role === UserRole.SUPERADMIN ? 'CONTROL MAESTRO' : user.role}
                            </span>
                        </div>

                        {/* Area */}
                        <div>
                            {user.area ? (
                                <span className="text-[11px] text-slate-700 font-black bg-white px-3 py-1.5 rounded-xl border border-slate-200 uppercase tracking-tighter shadow-sm">{user.area}</span>
                            ) : (
                                <span className="text-slate-300 font-mono text-xs">-</span>
                            )}
                        </div>

                        {/* Status */}
                        <div>
                            <div className={`flex items-center gap-2.5 px-3 py-1.5 rounded-full border w-fit ${(!user.status || user.status === 'ACTIVE') ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-slate-100 border-slate-200 text-slate-500'}`}>
