                            </div>
                        </div>

                        {/* Joined Date */}
                        <div className="flex items-center gap-2.5 text-[11px] text-slate-500 font-bold">
                            <Calendar size={14} className="text-slate-300"/>
                            {user.joinedAt ? new Date(user.joinedAt).toLocaleDateString() : '-'}
