                                className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white hover:shadow-md rounded-2xl transition-all border border-transparent hover:border-slate-100" 
                                title="Editar Perfil de Usuario"
                            >
                                <Edit2 size={20} strokeWidth={2.5}/>
                            </button>
                        </div>
                    </div>
                ))}

                {filteredUsers.length === 0 && (
                    <div className="p-20 text-center">
                        <UserIcon size={48} className="mx-auto text-slate-100 mb-4" />
                        <p className="text-slate-400 font-black uppercase tracking-[0.2em] text-sm">No se encontraron colaboradores</p>
                    </div>
                )}
             </div>
        </div>

        <NewUserModal 
            isOpen={isModalOpen} 
            onClose={() => setIsModalOpen(false)} 
            userToEdit={selectedUser}
        />
    </div>
  );
};
